fn replay(line: &str) -> String {
    let words: Vec<&str> = line.split(' ').collect();
    match words[..] {
        ["b64enc", hex] => format!("ok {}", base64::encode(&hex_bytes(hex))),
        ["b64dec", text] => match base64::decode(text.as_bytes()) {
            Some(bytes) => format!("ok {}", to_hex(&bytes)),
            None => "err".to_string(),
        },
        ["rc4", key, data] => {
            let mut data = hex_bytes(data);
            Rc4::new(&hex_bytes(key)).process(&mut data);
            format!("ok {}", to_hex(&data))
        }
        ["md4", chunks] => format!("ok {}", to_hex(&md4(&split_chunks(chunks).concat()))),
        ["md5", chunks] => {
            let mut hash = Md5::default();
            for chunk in split_chunks(chunks) {
                hash.update(&chunk);
            }
            format!("ok {}", to_hex(&hash.finalize()))
        }
        ["hmac", key, chunks] => {
            let mut hmac = HmacMd5::new(&hex_bytes(key));
            for chunk in split_chunks(chunks) {
                hmac.update(&chunk);
            }
            format!("ok {}", to_hex(&hmac.finalize()))
        }
        ["ntlm1key", secret] => {
            format!(
                "ok {}",
                to_hex(&keys::ntlm1_session_key(&hex_bytes(secret)))
            )
        }
        ["subkey", mode, key] => {
            let subkeys = keys::ntlm2_subkeys(mode_of(mode), &key16(key));
            format!(
                "ok {} {} {} {}",
                to_hex(&subkeys.send_sign),
                to_hex(&subkeys.send_seal),
                to_hex(&subkeys.recv_sign),
                to_hex(&subkeys.recv_seal),
            )
        }
        ["sess", mode, flags, key, ref ops @ ..] => {
            let mut session = Session::new(mode_of(mode), flags_of(flags), &key16(key));
            ops.iter()
                .map(|op| run_op(&mut session, op))
                .collect::<Vec<_>>()
                .join(" | ")
        }
        _ => panic!("unknown command {line}"),
    }
}

/// `cmd_sess` for one op: the buffers are passed to the message function in order, and the
/// result is reported after the call, so the rewritten buffers are the ones that are printed.
fn run_op(session: &mut Session, op: &str) -> String {
    let (name, items) = op.split_once(':').expect("op has a name");
    let mut storage: Vec<(u32, Vec<u8>)> = items
        .split(',')
        .map(|item| {
            let (kind, hex) = item.split_once('=').expect("buffer has a kind");
            (
                kind.parse().expect("buffer kind is a number"),
                hex_bytes(hex),
            )
        })
        .collect();
    let mut buffers: Vec<Buffer<'_>> = storage
        .iter_mut()
        .map(|(kind, data)| Buffer {
            kind: *kind,
            data: data.as_mut_slice(),
        })
        .collect();

    let result = match name {
        "mks" => session.make_signature(&mut buffers),
        "vfy" => session.verify_signature(&buffers),
        "seal" => session.seal_message(&mut buffers),
        "unseal" => session.unseal_message(&mut buffers),
        other => panic!("unknown op {other}"),
    };
    report(result, &buffers)
}

/// The `ok` or `err` head of `cmd_sess`, then each buffer as `KIND=HEX`. A STREAM shows at most
/// its first 16 bytes, as in the C harness.
fn report(result: Result<(), Error>, buffers: &[Buffer<'_>]) -> String {
    let head = match result {
        Ok(()) => "ok".to_string(),
        Err(error) => format!("err 0x{:08x}", error.code()),
    };
    let views: Vec<String> = buffers
        .iter()
        .map(|buffer| {
            let shown: &[u8] = match buffer.kind {
                SECBUFFER_STREAM => &buffer.data[..buffer.data.len().min(16)],
                _ => buffer.data,
            };
            format!("{}={}", buffer.kind, to_hex(shown))
        })
        .collect();
    format!("{head} {}", views.join(","))
}

fn mode_of(word: &str) -> Mode {
    match word {
        "1" => Mode::Client,
        "2" => Mode::Server,
        "3" => Mode::Both,
        other => panic!("bad mode {other}"),
    }
}

fn flags_of(word: &str) -> u32 {
    u32::from_str_radix(word.trim_start_matches("0x"), 16).expect("flags are hex")
}

fn key16(word: &str) -> [u8; 16] {
    hex_bytes(word).try_into().expect("16-byte key")
}

/// Hex text to bytes, with `-` for the empty string.
fn hex_bytes(word: &str) -> Vec<u8> {
    if word == "-" {
        return Vec::new();
    }
    word.as_bytes()
        .chunks(2)
        .map(|pair| {
            let text = std::str::from_utf8(pair).expect("hex digits");
            u8::from_str_radix(text, 16).expect("hex byte")
        })
        .collect()
}

fn split_chunks(words: &str) -> Vec<Vec<u8>> {
    words.split(',').map(hex_bytes).collect()
}

fn to_hex(bytes: &[u8]) -> String {
    bytes.iter().map(|byte| format!("{byte:02x}")).collect()
}

